00084 static inline int64_t square( const int d ) { return d * (int64_t)d; }
00085 
00086 template<int signedMode> std::pair<int64_t,int64_t> fwdTransformCbCr( const PelBuf &resCb, const PelBuf &resCr, PelBuf& resC1, PelBuf& resC2 )
00087 {
00088   const Pel*  cb  = resCb.buf;
00089   const Pel*  cr  = resCr.buf;
00090   Pel*        c1  = resC1.buf;
00091   Pel*        c2  = resC2.buf;
00092   int64_t     d1  = 0;
00093   int64_t     d2  = 0;
00094   for( SizeType y = 0; y < resCb.height; y++, cb += resCb.stride, cr += resCr.stride, c1 += resC1.stride, c2 += resC2.stride )
00095   {
00096     for( SizeType x = 0; x < resCb.width; x++ )
00097     {
00098       int cbx = cb[x], crx = cr[x];
00099       if      ( signedMode ==  1 )
00100       {
00101         c1[x] = Pel( ( 4*cbx + 2*crx ) / 5 );
00102         d1   += square( cbx - c1[x] ) + square( crx - (c1[x]>>1) );
00103       }
00104       else if ( signedMode == -1 )
00105       {
00106         c1[x] = Pel( ( 4*cbx - 2*crx ) / 5 );
00107         d1   += square( cbx - c1[x] ) + square( crx - (-c1[x]>>1) );
00108       }
00109       else if ( signedMode ==  2 )
00110       {
00111         c1[x] = Pel( ( cbx + crx ) / 2 );
00112         d1   += square( cbx - c1[x] ) + square( crx - c1[x] );
00113       }
00114       else if ( signedMode == -2 )
00115       {
00116         c1[x] = Pel( ( cbx - crx ) / 2 );
00117         d1   += square( cbx - c1[x] ) + square( crx + c1[x] );
00118       }
00119       else if ( signedMode ==  3 )
00120       {
00121         c2[x] = Pel( ( 4*crx + 2*cbx ) / 5 );
00122         d1   += square( cbx - (c2[x]>>1) ) + square( crx - c2[x] );
00123       }
00124       else if ( signedMode == -3 )
00125       {
00126         c2[x] = Pel( ( 4*crx - 2*cbx ) / 5 );
00127         d1   += square( cbx - (-c2[x]>>1) ) + square( crx - c2[x] );
00128       }
00129       else
00130       {
00131         d1   += square( cbx );
00132         d2   += square( crx );
00133       }
00134     }
00135   }
00136   return std::make_pair(d1,d2);
00137 }
00138 
00139 template<int signedMode> void invTransformCbCr( PelBuf &resCb, PelBuf &resCr )
00140 {
00141   Pel*  cb  = resCb.buf;
00142   Pel*  cr  = resCr.buf;
00143   for( SizeType y = 0; y < resCb.height; y++, cb += resCb.stride, cr += resCr.stride )
00144   {
00145     for( SizeType x = 0; x < resCb.width; x++ )
00146     {
00147       if (signedMode == 1)
00148       {
00149         cr[x] = cb[x] >> 1;
00150       }
00151       else if (signedMode == -1)
00152       {
00153         cr[x] = -cb[x] >> 1;
00154       }
00155       else if (signedMode == 2)
00156       {
00157         cr[x] = cb[x];
00158       }
00159       else if (signedMode == -2)
00160       {
00161         // non-normative clipping to prevent 16-bit overflow
00162         cr[x] = (cb[x] == -32768 && sizeof(Pel) == 2) ? 32767 : -cb[x];
00163       }
00164       else if (signedMode == 3)
00165       {
00166         cb[x] = cr[x] >> 1;
00167       }
00168       else if (signedMode == -3)
00169       {
00170         cb[x] = -cr[x] >> 1;
00171       }
00172     }
00173   }
00174 }
