00179 TrQuant::TrQuant() : m_quant( nullptr )
00180 {
00181   // allocate temporary buffers
00182   {
00183     m_invICT      = m_invICTMem + maxAbsIctMode;
00184     m_invICT[ 0]  = invTransformCbCr< 0>;
00185     m_invICT[ 1]  = invTransformCbCr< 1>;
