00187     m_invICT[ 2]  = invTransformCbCr< 2>;
00188     m_invICT[-2]  = invTransformCbCr<-2>;
00189     m_invICT[ 3]  = invTransformCbCr< 3>;
00190     m_invICT[-3]  = invTransformCbCr<-3>;
