00247 void TrQuant::fwdLfnstNxN( TCoeff* src, TCoeff* dst, const uint32_t mode, const uint32_t index, const uint32_t size, int zeroOutSize )
00248 {
00249   const int8_t* trMat  = ( size > 4 ) ? g_lfnst8x8[ mode ][ index ][ 0 ] : g_lfnst4x4[ mode ][ index ][ 0 ];
00250   const int     trSize = ( size > 4 ) ? 48 : 16;
00251   TCoeff           coef;
00252   TCoeff*          out    = dst;
00253   assert( index < 3 );
00254 
00255   for( int j = 0; j < zeroOutSize; j++ )
00256   {
00257     TCoeff*          srcPtr   = src;
00258     const int8_t* trMatTmp = trMat;
00259     coef = 0;
00260     for( int i = 0; i < trSize; i++ )
00261     {
00262       coef += *srcPtr++ * *trMatTmp++;
00263     }
00264     *out++ = ( coef + 64 ) >> 7;
00265     trMat += trSize;
00266   }
00267 
00268   std::fill_n( out, trSize - zeroOutSize, 0 );
00269 }
00270 
00271 void TrQuant::invLfnstNxN( TCoeff* src, TCoeff* dst, const uint32_t mode, const uint32_t index, const uint32_t size, int zeroOutSize, const int maxLog2TrDynamicRange )
00272 {
00273   const TCoeff    outputMinimum         = -( 1 << maxLog2TrDynamicRange );
00274   const TCoeff    outputMaximum         =  ( 1 << maxLog2TrDynamicRange ) - 1;
00275   const int8_t*   trMat                 =  ( size > 4 ) ? g_lfnst8x8[ mode ][ index ][ 0 ] : g_lfnst4x4[ mode ][ index ][ 0 ];
00276   const int       trSize                =  ( size > 4 ) ? 48 : 16;
00277   TCoeff          resi;
00278   TCoeff*         out                   =  dst;
00279   assert( index < 3 );
00280 
00281   for( int j = 0; j < trSize; j++ )
00282   {
00283     resi = 0;
00284     const int8_t* trMatTmp = trMat;
00285     TCoeff*       srcPtr   = src;
00286     for( int i = 0; i < zeroOutSize; i++ )
00287     {
00288       resi += *srcPtr++ * *trMatTmp;
00289       trMatTmp += trSize;
00290     }
00291     *out++ = Clip3<TCoeff>( outputMinimum, outputMaximum, ( resi + 64 ) >> 7 );
00292     trMat++;
00293   }
00294 }
