00296 uint32_t TrQuant::getLFNSTIntraMode( int wideAngPredMode )
00297 {
00298   uint32_t intraMode;
00299 
00300   if( wideAngPredMode < 0 )
00301   {
00302     intraMode = ( uint32_t ) ( wideAngPredMode + ( NUM_EXT_LUMA_MODE >> 1 ) + NUM_LUMA_MODE );
00303   }
00304   else if( wideAngPredMode >= NUM_LUMA_MODE )
00305   {
00306     intraMode = ( uint32_t ) ( wideAngPredMode + ( NUM_EXT_LUMA_MODE >> 1 ) );
00307   }
00308   else
00309   {
00310     intraMode = ( uint32_t ) wideAngPredMode;
00311   }
00312 
00313   return intraMode;
00314 }
00315 
00316 bool TrQuant::getTransposeFlag( uint32_t intraMode )
00317 {
00318   return ( ( intraMode >= NUM_LUMA_MODE ) && ( intraMode >= ( NUM_LUMA_MODE + ( NUM_EXT_LUMA_MODE >> 1 ) ) ) ) ||
00319          ( ( intraMode <  NUM_LUMA_MODE ) && ( intraMode >  DIA_IDX ) );
00320 }
