00322 void TrQuant::xInvLfnst( const TransformUnit &tu, const ComponentID compID )
00323 {
00324   const int maxLog2TrDynamicRange = tu.cs->sps->getMaxLog2TrDynamicRange(toChannelType(compID));
00325   const CompArea& area     = tu.blocks[ compID ];
00326   const uint32_t  width    = area.width;
00327   const uint32_t  height   = area.height;
00328   const uint32_t  lfnstIdx = tu.cu->lfnstIdx;
00329   if( lfnstIdx && tu.mtsIdx[compID] != MTS_SKIP && (tu.cu->isSepTree() ? true : isLuma(compID)) )
00330   {
00331     const bool whge3 = width >= 8 && height >= 8;
00332     const ScanElement * scan = whge3 ? g_coefTopLeftDiagScan8x8[ gp_sizeIdxInfo->idxFrom( width ) ] : g_scanOrder[ SCAN_GROUPED_4x4 ][ SCAN_DIAG ][ gp_sizeIdxInfo->idxFrom( width ) ][ gp_sizeIdxInfo->idxFrom( height ) ];
00333     uint32_t intraMode = PU::getFinalIntraMode( *tu.cs->getPU( area.pos(), toChannelType( compID ) ), toChannelType( compID ) );
00334 
00335     if( PU::isLMCMode( tu.cs->getPU( area.pos(), toChannelType( compID ) )->intraDir[ toChannelType( compID ) ] ) )
00336     {
00337       intraMode = PU::getCoLocatedIntraLumaMode( *tu.cs->getPU( area.pos(), toChannelType( compID ) ) );
00338     }
00339     if (PU::isMIP(*tu.cs->getPU(area.pos(), toChannelType(compID)), toChannelType(compID)))
00340     {
00341       intraMode = PLANAR_IDX;
00342     }
00343     CHECK( intraMode >= NUM_INTRA_MODE - 1, "Invalid intra mode" );
00344 
00345     if( lfnstIdx < 3 )
00346     {
00347       intraMode = getLFNSTIntraMode( PU::getWideAngle( tu, intraMode, compID ) );
00348 #if RExt__DECODER_DEBUG_TOOL_STATISTICS
00349       CodingStatistics::IncrementStatisticTool( CodingStatisticsClassType { STATS__TOOL_LFNST, width, height, compID } );
00350 #endif
00351       bool          transposeFlag   = getTransposeFlag( intraMode );
00352       const int     sbSize          = whge3 ? 8 : 4;
00353       bool          tu4x4Flag       = ( width == 4 && height == 4 );
00354       bool          tu8x8Flag       = ( width == 8 && height == 8 );
00355       TCoeff*       lfnstTemp;
00356       TCoeff*       coeffTemp;
00357       int           y;
00358       lfnstTemp   = m_tempInMatrix;   // inverse spectral rearrangement
00359       coeffTemp   = m_tempCoeff;
00360       TCoeff *dst = lfnstTemp;
00361 
00362       const ScanElement *scanPtr = scan;
00363       for (y = 0; y < 16; y++)
00364       {
00365         *dst++ = coeffTemp[scanPtr->idx];
00366         scanPtr++;
00367       }
00368 
00369       invLfnstNxN(m_tempInMatrix, m_tempOutMatrix, g_lfnstLut[intraMode], lfnstIdx - 1, sbSize,
00370                   (tu4x4Flag || tu8x8Flag) ? 8 : 16, maxLog2TrDynamicRange);
00371       lfnstTemp = m_tempOutMatrix;   // inverse spectral rearrangement
00372 
00373       if (transposeFlag)
00374       {
00375         if (sbSize == 4)
00376         {
00377           for (y = 0; y < 4; y++)
00378           {
00379             coeffTemp[0] = lfnstTemp[0];
00380             coeffTemp[1] = lfnstTemp[4];
00381             coeffTemp[2] = lfnstTemp[8];
00382             coeffTemp[3] = lfnstTemp[12];
00383             lfnstTemp++;
00384             coeffTemp += width;
00385           }
00386         }
00387         else   // ( sbSize == 8 )
00388         {
00389           for (y = 0; y < 8; y++)
00390           {
00391             coeffTemp[0] = lfnstTemp[0];
00392             coeffTemp[1] = lfnstTemp[8];
00393             coeffTemp[2] = lfnstTemp[16];
00394             coeffTemp[3] = lfnstTemp[24];
00395             if (y < 4)
00396             {
00397               coeffTemp[4] = lfnstTemp[32];
00398               coeffTemp[5] = lfnstTemp[36];
00399               coeffTemp[6] = lfnstTemp[40];
00400               coeffTemp[7] = lfnstTemp[44];
00401             }
00402             lfnstTemp++;
00403             coeffTemp += width;
00404           }
00405         }
00406       }
00407       else
00408       {
00409         for (y = 0; y < sbSize; y++)
00410         {
00411           uint32_t uiStride = (y < 4) ? sbSize : 4;
00412           ::memcpy(coeffTemp, lfnstTemp, uiStride * sizeof(TCoeff));
00413           lfnstTemp += uiStride;
00414           coeffTemp += width;
00415         }
00416       }
00417     }
00418   }
00419 }
00420 
00421 void TrQuant::xFwdLfnst( const TransformUnit &tu, const ComponentID compID, const bool loadTr )
00422 {
00423   const CompArea& area     = tu.blocks[ compID ];
00424   const uint32_t  width    = area.width;
00425   const uint32_t  height   = area.height;
00426   const uint32_t  lfnstIdx = tu.cu->lfnstIdx;
00427   if( lfnstIdx && tu.mtsIdx[compID] != MTS_SKIP && (tu.cu->isSepTree() ? true : isLuma(compID)) )
00428   {
00429     const bool whge3 = width >= 8 && height >= 8;
00430     const ScanElement * scan = whge3 ? g_coefTopLeftDiagScan8x8[ gp_sizeIdxInfo->idxFrom( width ) ] : g_scanOrder[ SCAN_GROUPED_4x4 ][ SCAN_DIAG ][ gp_sizeIdxInfo->idxFrom( width ) ][ gp_sizeIdxInfo->idxFrom( height ) ];
00431     uint32_t intraMode = PU::getFinalIntraMode( *tu.cs->getPU( area.pos(), toChannelType( compID ) ), toChannelType( compID ) );
00432 
00433     if( PU::isLMCMode( tu.cs->getPU( area.pos(), toChannelType( compID ) )->intraDir[ toChannelType( compID ) ] ) )
00434     {
00435       intraMode = PU::getCoLocatedIntraLumaMode( *tu.cs->getPU( area.pos(), toChannelType( compID ) ) );
00436     }
00437     if (PU::isMIP(*tu.cs->getPU(area.pos(), toChannelType(compID)), toChannelType(compID)))
00438     {
00439       intraMode = PLANAR_IDX;
00440     }
00441     CHECK( intraMode >= NUM_INTRA_MODE - 1, "Invalid intra mode" );
00442 
00443     if( lfnstIdx < 3 )
00444     {
00445       intraMode = getLFNSTIntraMode( PU::getWideAngle( tu, intraMode, compID ) );
00446 
00447       bool            transposeFlag   = getTransposeFlag( intraMode );
00448       const int       sbSize          = whge3 ? 8 : 4;
00449       bool            tu4x4Flag       = ( width == 4 && height == 4 );
00450       bool            tu8x8Flag       = ( width == 8 && height == 8 );
00451       TCoeff*         lfnstTemp;
00452       TCoeff*         coeffTemp;
00453       TCoeff *        tempCoeff = loadTr ? m_mtsCoeffs[tu.mtsIdx[compID]] : m_tempCoeff;
00454 
00455       int y;
00456       lfnstTemp = m_tempInMatrix;   // forward low frequency non-separable transform
00457       coeffTemp = tempCoeff;
00458 
00459       if (transposeFlag)
00460       {
00461         if (sbSize == 4)
00462         {
00463           for (y = 0; y < 4; y++)
00464           {
00465             lfnstTemp[0]  = coeffTemp[0];
00466             lfnstTemp[4]  = coeffTemp[1];
00467             lfnstTemp[8]  = coeffTemp[2];
00468             lfnstTemp[12] = coeffTemp[3];
00469             lfnstTemp++;
00470             coeffTemp += width;
00471           }
00472         }
00473         else   // ( sbSize == 8 )
00474         {
00475           for (y = 0; y < 8; y++)
00476           {
00477             lfnstTemp[0]  = coeffTemp[0];
00478             lfnstTemp[8]  = coeffTemp[1];
00479             lfnstTemp[16] = coeffTemp[2];
00480             lfnstTemp[24] = coeffTemp[3];
00481             if (y < 4)
00482             {
00483               lfnstTemp[32] = coeffTemp[4];
00484               lfnstTemp[36] = coeffTemp[5];
00485               lfnstTemp[40] = coeffTemp[6];
00486               lfnstTemp[44] = coeffTemp[7];
00487             }
00488             lfnstTemp++;
00489             coeffTemp += width;
00490           }
00491         }
00492       }
00493       else
00494       {
00495         for (y = 0; y < sbSize; y++)
00496         {
00497           uint32_t uiStride = (y < 4) ? sbSize : 4;
00498           ::memcpy(lfnstTemp, coeffTemp, uiStride * sizeof(TCoeff));
00499           lfnstTemp += uiStride;
00500           coeffTemp += width;
00501         }
00502       }
00503 
00504       fwdLfnstNxN(m_tempInMatrix, m_tempOutMatrix, g_lfnstLut[intraMode], lfnstIdx - 1, sbSize,
00505                   (tu4x4Flag || tu8x8Flag) ? 8 : 16);
00506 
00507       lfnstTemp         = m_tempOutMatrix;   // forward spectral rearrangement
00508       coeffTemp         = tempCoeff;
00509       int lfnstCoeffNum = (sbSize == 4) ? sbSize * sbSize : 48;
00510 
00511       const ScanElement *scanPtr = scan;
00512 
00513       for (y = 0; y < lfnstCoeffNum; y++)
00514       {
00515         coeffTemp[scanPtr->idx] = *lfnstTemp++;
00516         scanPtr++;
00517       }
00518     }
00519   }
00520 }
00521 
00522 
00523 void TrQuant::invTransformNxN( TransformUnit &tu, const ComponentID &compID, PelBuf &pResi, const QpParam &cQP )
00524 {
00525   const CompArea &area    = tu.blocks[compID];
00526   const uint32_t uiWidth      = area.width;
00527   const uint32_t uiHeight     = area.height;
00528 
00529   CHECK( uiWidth > tu.cs->sps->getMaxTbSize() || uiHeight > tu.cs->sps->getMaxTbSize(), "Maximal allowed transformation size exceeded!" );
00530   CoeffBuf tempCoeff = CoeffBuf(m_tempCoeff, area);
00531   xDeQuant(tu, tempCoeff, compID, cQP);
00532 
00533   DTRACE_COEFF_BUF(D_TCOEFF, tempCoeff, tu, tu.cu->predMode, compID);
00534 
00535   if (tu.cs->sps->getUseLFNST())
00536   {
00537     xInvLfnst(tu, compID);
00538   }
00539 
00540   if (tu.mtsIdx[compID] == MTS_SKIP)
00541   {
00542     xITransformSkip(tempCoeff, pResi, tu, compID);
00543   }
00544   else
00545   {
00546     xIT(tu, compID, tempCoeff, pResi);
00547   }
00548 
00549   //DTRACE_BLOCK_COEFF(tu.getCoeffs(compID), tu, tu.cu->predMode, compID);
00550   DTRACE_PEL_BUF( D_RESIDUALS, pResi, tu, tu.cu->predMode, compID);
00551 }
00552 
00553 std::pair<int64_t,int64_t> TrQuant::fwdTransformICT( const TransformUnit &tu, const PelBuf &resCb, const PelBuf &resCr, PelBuf &resC1, PelBuf &resC2, int jointCbCr )
00554 {
00555   CHECK( Size(resCb) != Size(resCr), "resCb and resCr have different sizes" );
00556   CHECK( Size(resCb) != Size(resC1), "resCb and resC1 have different sizes" );
00557   CHECK( Size(resCb) != Size(resC2), "resCb and resC2 have different sizes" );
00558   return (*m_fwdICT[ TU::getICTMode(tu, jointCbCr) ])( resCb, resCr, resC1, resC2 );
00559 }
00560 
00561 void TrQuant::invTransformICT( const TransformUnit &tu, PelBuf &resCb, PelBuf &resCr )
00562 {
00563   CHECK( Size(resCb) != Size(resCr), "resCb and resCr have different sizes" );
00564   (*m_invICT[ TU::getICTMode(tu) ])( resCb, resCr );
00565 }
00566 
00567 std::vector<int> TrQuant::selectICTCandidates( const TransformUnit &tu, CompStorage* resCb, CompStorage* resCr )
00568 {
00569   CHECK( !resCb[0].valid() || !resCr[0].valid(), "standard components are not valid" );
00570 
00571   if( !CU::isIntra( *tu.cu ) )
00572   {
00573     int cbfMask = 3;
00574     resCb[cbfMask].create( tu.blocks[COMPONENT_Cb] );
00575     resCr[cbfMask].create( tu.blocks[COMPONENT_Cr] );
00576     fwdTransformICT( tu, resCb[0], resCr[0], resCb[cbfMask], resCr[cbfMask], cbfMask );
00577     std::vector<int> cbfMasksToTest;
00578     cbfMasksToTest.push_back( cbfMask );
00579     return cbfMasksToTest;
00580   }
00581 
00582   std::pair<int64_t,int64_t> pairDist[4];
00583   for( int cbfMask = 0; cbfMask < 4; cbfMask++ )
00584   {
00585     if( cbfMask )
00586     {
00587       CHECK( resCb[cbfMask].valid() || resCr[cbfMask].valid(), "target components for cbfMask=" << cbfMask << " are already present" );
00588       resCb[cbfMask].create( tu.blocks[COMPONENT_Cb] );
00589       resCr[cbfMask].create( tu.blocks[COMPONENT_Cr] );
00590     }
00591     pairDist[cbfMask] = fwdTransformICT( tu, resCb[0], resCr[0], resCb[cbfMask], resCr[cbfMask], cbfMask );
00592   }
00593 
00594   std::vector<int> cbfMasksToTest;
00595   int64_t minDist1  = std::min<int64_t>( pairDist[0].first, pairDist[0].second );
00596   int64_t minDist2  = std::numeric_limits<int64_t>::max();
00597   int     cbfMask1  = 0;
00598   int     cbfMask2  = 0;
00599   for( int cbfMask : { 1, 2, 3 } )
00600   {
00601     if( pairDist[cbfMask].first < minDist1 )
00602     {
00603       cbfMask2  = cbfMask1; minDist2  = minDist1;
00604       cbfMask1  = cbfMask;  minDist1  = pairDist[cbfMask1].first;
00605     }
00606     else if( pairDist[cbfMask].first < minDist2 )
00607     {
00608       cbfMask2  = cbfMask;  minDist2  = pairDist[cbfMask2].first;
00609     }
00610   }
00611   if( cbfMask1 )
00612   {
00613     cbfMasksToTest.push_back( cbfMask1 );
00614   }
00615   if( cbfMask2 && ( ( minDist2 < (9*minDist1)/8 ) || ( !cbfMask1 && minDist2 < (3*minDist1)/2 ) ) )
00616   {
00617     cbfMasksToTest.push_back( cbfMask2 );
00618   }
00619 
00620   return cbfMasksToTest;
00621 }
