00625 // ------------------------------------------------------------------------------------------------
00626 // Logical transform
00627 // ------------------------------------------------------------------------------------------------
00628 
00629 void TrQuant::getTrTypes(const TransformUnit tu, const ComponentID compID, int &trTypeHor, int &trTypeVer)
00630 {
00631   const bool isExplicitMTS = (CU::isIntra(*tu.cu) ? tu.cs->sps->getUseIntraMTS() : tu.cs->sps->getUseInterMTS() && CU::isInter(*tu.cu)) && isLuma(compID);
00632   const bool isImplicitMTS = CU::isIntra(*tu.cu) && tu.cs->sps->getUseImplicitMTS() && isLuma(compID) && tu.cu->lfnstIdx == 0 && tu.cu->mipFlag == 0;
00633   const bool isISP = CU::isIntra(*tu.cu) && tu.cu->ispMode && isLuma(compID);
00634   const bool isSBT = CU::isInter(*tu.cu) && tu.cu->sbtInfo && isLuma(compID);
00635 
00636   trTypeHor = DCT2;
00637   trTypeVer = DCT2;
00638 
00639   if (isISP && tu.cu->lfnstIdx)
00640   {
00641     return;
00642   }
00643 
00644   if (!tu.cs->sps->getUseMTS())
00645   {
00646     return;
00647   }
00648 
00649   if (isImplicitMTS || isISP)
00650   {
00651     int  width = tu.blocks[compID].width;
00652     int  height = tu.blocks[compID].height;
00653     bool widthDstOk = width >= 4 && width <= 16;
00654     bool heightDstOk = height >= 4 && height <= 16;
00655 
00656     if (widthDstOk)
00657     {
00658       trTypeHor = DST7;
00659     }
00660     if (heightDstOk)
00661     {
00662       trTypeVer = DST7;
00663     }
00664     return;
00665   }
00666 
00667 
00668   if (isSBT)
00669   {
00670     uint8_t sbtIdx = tu.cu->getSbtIdx();
00671     uint8_t sbtPos = tu.cu->getSbtPos();
00672 
00673     if( sbtIdx == SBT_VER_HALF || sbtIdx == SBT_VER_QUAD )
00674     {
00675       assert( tu.lwidth() <= MTS_INTER_MAX_CU_SIZE );
00676       if( tu.lheight() > MTS_INTER_MAX_CU_SIZE )
00677       {
00678         trTypeHor = trTypeVer = DCT2;
00679       }
00680       else
00681       {
00682         if (sbtPos == SBT_POS0)
00683         {
00684           trTypeHor = DCT8;
00685           trTypeVer = DST7;
00686         }
00687         else
00688         {
00689           trTypeHor = DST7;
00690           trTypeVer = DST7;
00691         }
00692       }
00693     }
00694     else
00695     {
00696       assert( tu.lheight() <= MTS_INTER_MAX_CU_SIZE );
00697       if( tu.lwidth() > MTS_INTER_MAX_CU_SIZE )
00698       {
00699         trTypeHor = trTypeVer = DCT2;
00700       }
00701       else
00702       {
00703         if (sbtPos == SBT_POS0)
00704         {
00705           trTypeHor = DST7;
00706           trTypeVer = DCT8;
00707         }
00708         else
00709         {
00710           trTypeHor = DST7;
00711           trTypeVer = DST7;
00712         }
00713       }
00714     }
00715     return;
00716   }
00717 
00718   if (isExplicitMTS)
00719   {
00720     if (tu.mtsIdx[compID] > MTS_SKIP)
00721     {
00722       int indHor = (tu.mtsIdx[compID] - MTS_DST7_DST7) & 1;
00723       int indVer = (tu.mtsIdx[compID] - MTS_DST7_DST7) >> 1;
00724       trTypeHor = indHor ? DCT8 : DST7;
00725       trTypeVer = indVer ? DCT8 : DST7;
00726     }
00727   }
00728 }
00729 
00730 void TrQuant::xT( const TransformUnit &tu, const ComponentID &compID, const CPelBuf &resi, CoeffBuf &dstCoeff, const int width, const int height )
00731 {
00732   const unsigned maxLog2TrDynamicRange  = tu.cs->sps->getMaxLog2TrDynamicRange( toChannelType( compID ) );
00733   const unsigned bitDepth               = tu.cs->sps->getBitDepth(              toChannelType( compID ) );
00734   const int      TRANSFORM_MATRIX_SHIFT = g_transformMatrixShift[TRANSFORM_FORWARD];
00735   const uint32_t transformWidthIndex    = floorLog2(width ) - 1;  // nLog2WidthMinus1, since transform start from 2-point
00736   const uint32_t transformHeightIndex   = floorLog2(height) - 1;  // nLog2HeightMinus1, since transform start from 2-point
00737 
00738   int trTypeHor = DCT2;
00739   int trTypeVer = DCT2;
00740 
00741   getTrTypes ( tu, compID, trTypeHor, trTypeVer );
00742 
00743   int  skipWidth  = ( trTypeHor != DCT2 && width  == 32 ) ? 16 : width  > JVET_C0024_ZERO_OUT_TH ? width  - JVET_C0024_ZERO_OUT_TH : 0;
00744   int  skipHeight = ( trTypeVer != DCT2 && height == 32 ) ? 16 : height > JVET_C0024_ZERO_OUT_TH ? height - JVET_C0024_ZERO_OUT_TH : 0;
00745   if( tu.cs->sps->getUseLFNST() && tu.cu->lfnstIdx )
00746   {
00747     if( (width == 4 && height > 4) || (width > 4 && height == 4) )
00748     {
00749       skipWidth  = width  - 4;
00750       skipHeight = height - 4;
00751     }
00752     else if( (width >= 8 && height >= 8) )
00753     {
00754       skipWidth  = width  - 8;
00755       skipHeight = height - 8;
00756     }
00757   }
00758 
00759 #if RExt__DECODER_DEBUG_TOOL_STATISTICS
00760   if ( trTypeHor != DCT2 )
00761   {
00762     CodingStatistics::IncrementStatisticTool( CodingStatisticsClassType{ STATS__TOOL_EMT, uint32_t( width ), uint32_t( height ), compID } );
00763   }
00764 #endif
00765 
00766   ALIGN_DATA( MEMORY_ALIGN_DEF_SIZE, TCoeff block[MAX_TB_SIZEY * MAX_TB_SIZEY] );
00767 
00768   const Pel *resiBuf    = resi.buf;
00769   const int  resiStride = resi.stride;
00770 
00771   for( int y = 0; y < height; y++ )
00772   {
00773     for( int x = 0; x < width; x++ )
00774     {
00775       block[( y * width ) + x] = resiBuf[( y * resiStride ) + x];
00776     }
00777   }
00778 
00779   if( width > 1 && height > 1 ) // 2-D transform
00780   {
00781     const int      shift_1st              = ((floorLog2(width )) + bitDepth + TRANSFORM_MATRIX_SHIFT) - maxLog2TrDynamicRange + COM16_C806_TRANS_PREC;
00782     const int      shift_2nd              =  (floorLog2(height))            + TRANSFORM_MATRIX_SHIFT                          + COM16_C806_TRANS_PREC;
00783     CHECK( shift_1st < 0, "Negative shift" );
00784     CHECK( shift_2nd < 0, "Negative shift" );
00785     TCoeff *tmp = (TCoeff *) alloca(width * height * sizeof(TCoeff));
00786 
00787     fastFwdTrans[trTypeHor][transformWidthIndex](block, tmp, shift_1st, height, 0, skipWidth);
00788     fastFwdTrans[trTypeVer][transformHeightIndex](tmp, dstCoeff.buf, shift_2nd, width, skipWidth, skipHeight);
00789   }
00790   else if( height == 1 ) //1-D horizontal transform
00791   {
00792     const int      shift              = ((floorLog2(width )) + bitDepth + TRANSFORM_MATRIX_SHIFT) - maxLog2TrDynamicRange + COM16_C806_TRANS_PREC;
00793     CHECK( shift < 0, "Negative shift" );
00794     CHECKD( ( transformWidthIndex < 0 ), "There is a problem with the width." );
00795     fastFwdTrans[trTypeHor][transformWidthIndex]( block, dstCoeff.buf, shift, 1, 0, skipWidth );
00796   }
00797   else //if (iWidth == 1) //1-D vertical transform
00798   {
00799     int shift = ( ( floorLog2(height) ) + bitDepth + TRANSFORM_MATRIX_SHIFT ) - maxLog2TrDynamicRange + COM16_C806_TRANS_PREC;
00800     CHECK( shift < 0, "Negative shift" );
00801     CHECKD( ( transformHeightIndex < 0 ), "There is a problem with the height." );
00802     fastFwdTrans[trTypeVer][transformHeightIndex]( block, dstCoeff.buf, shift, 1, 0, skipHeight );
00803   }
00804 }
00805 
00806 void TrQuant::xIT( const TransformUnit &tu, const ComponentID &compID, const CCoeffBuf &pCoeff, PelBuf &pResidual )
00807 {
00808   const int      width                  = pCoeff.width;
00809   const int      height                 = pCoeff.height;
00810   const unsigned maxLog2TrDynamicRange  = tu.cs->sps->getMaxLog2TrDynamicRange( toChannelType( compID ) );
00811   const unsigned bitDepth               = tu.cs->sps->getBitDepth(              toChannelType( compID ) );
00812   const int      TRANSFORM_MATRIX_SHIFT = g_transformMatrixShift[TRANSFORM_INVERSE];
00813   const TCoeff   clipMinimum            = -( 1 << maxLog2TrDynamicRange );
00814   const TCoeff   clipMaximum            =  ( 1 << maxLog2TrDynamicRange ) - 1;
00815   const TCoeff   pelMinimum             = std::numeric_limits<Pel>::min();
00816   const TCoeff   pelMaximum             = std::numeric_limits<Pel>::max();
00817   const uint32_t transformWidthIndex    = floorLog2(width ) - 1;                                // nLog2WidthMinus1, since transform start from 2-point
00818   const uint32_t transformHeightIndex   = floorLog2(height) - 1;                                // nLog2HeightMinus1, since transform start from 2-point
00819 
00820   int trTypeHor = DCT2;
00821   int trTypeVer = DCT2;
00822 
00823   getTrTypes ( tu, compID, trTypeHor, trTypeVer );
00824   int skipWidth  = ( trTypeHor != DCT2 && width  == 32 ) ? 16 : width  > JVET_C0024_ZERO_OUT_TH ? width  - JVET_C0024_ZERO_OUT_TH : 0;
00825   int skipHeight = ( trTypeVer != DCT2 && height == 32 ) ? 16 : height > JVET_C0024_ZERO_OUT_TH ? height - JVET_C0024_ZERO_OUT_TH : 0;
00826   if( tu.cs->sps->getUseLFNST() && tu.cu->lfnstIdx )
00827   {
00828     if( (width == 4 && height > 4) || (width > 4 && height == 4) )
00829     {
00830       skipWidth  = width  - 4;
00831       skipHeight = height - 4;
00832     }
00833     else if( (width >= 8 && height >= 8) )
00834     {
00835       skipWidth  = width  - 8;
00836       skipHeight = height - 8;
00837     }
00838   }
00839 
00840   TCoeff *block = ( TCoeff * ) alloca( width * height * sizeof( TCoeff ) );
00841 
00842   if( width > 1 && height > 1 ) //2-D transform
00843   {
00844     const int      shift_1st              =   TRANSFORM_MATRIX_SHIFT + 1 + COM16_C806_TRANS_PREC; // 1 has been added to shift_1st at the expense of shift_2nd
00845     const int      shift_2nd              = ( TRANSFORM_MATRIX_SHIFT + maxLog2TrDynamicRange - 1 ) - bitDepth + COM16_C806_TRANS_PREC;
00846     CHECK( shift_1st < 0, "Negative shift" );
00847     CHECK( shift_2nd < 0, "Negative shift" );
00848     TCoeff *tmp = ( TCoeff * ) alloca( width * height * sizeof( TCoeff ) );
00849     fastInvTrans[trTypeVer][transformHeightIndex](pCoeff.buf, tmp, shift_1st, width, skipWidth, skipHeight, clipMinimum, clipMaximum);
00850     fastInvTrans[trTypeHor][transformWidthIndex] (tmp,      block, shift_2nd, height,        0, skipWidth,  pelMinimum,  pelMaximum);
00851   }
00852   else if( width == 1 ) //1-D vertical transform
00853   {
00854     int shift = ( TRANSFORM_MATRIX_SHIFT + maxLog2TrDynamicRange - 1 ) - bitDepth + COM16_C806_TRANS_PREC;
00855     CHECK( shift < 0, "Negative shift" );
00856     CHECK( ( transformHeightIndex < 0 ), "There is a problem with the height." );
00857     fastInvTrans[trTypeVer][transformHeightIndex]( pCoeff.buf, block, shift + 1, 1, 0, skipHeight, pelMinimum, pelMaximum );
00858   }
00859   else //if(iHeight == 1) //1-D horizontal transform
00860   {
00861     const int      shift              = ( TRANSFORM_MATRIX_SHIFT + maxLog2TrDynamicRange - 1 ) - bitDepth + COM16_C806_TRANS_PREC;
00862     CHECK( shift < 0, "Negative shift" );
00863     CHECK( ( transformWidthIndex < 0 ), "There is a problem with the width." );
00864     fastInvTrans[trTypeHor][transformWidthIndex]( pCoeff.buf, block, shift + 1, 1, 0, skipWidth, pelMinimum, pelMaximum );
00865   }
00866 
00867   Pel *resiBuf    = pResidual.buf;
00868   int  resiStride = pResidual.stride;
00869 
00870   for( int y = 0; y < height; y++ )
00871   {
00872     for( int x = 0; x < width; x++ )
00873     {
00874       resiBuf[( y * resiStride ) + x] = Pel( block[( y * width ) + x] );
00875     }
00876   }
00877 }
00878 
00881 void TrQuant::xITransformSkip(const CCoeffBuf     &pCoeff,
00882                                     PelBuf        &pResidual,
00883                               const TransformUnit &tu,
00884                               const ComponentID   &compID)
00885 {
00886   const CompArea &area      = tu.blocks[compID];
00887   const int width           = area.width;
00888   const int height          = area.height;
00889 
00890   for (uint32_t y = 0; y < height; y++)
00891   {
00892     for (uint32_t x = 0; x < width; x++)
00893     {
00894       pResidual.at(x, y) = Pel(pCoeff.at(x, y));
00895     }
00896   }
00897 }
