00899 void TrQuant::xQuant(TransformUnit &tu, const ComponentID &compID, const CCoeffBuf &pSrc, TCoeff &uiAbsSum, const QpParam &cQP, const Ctx& ctx)
00900 {
00901   m_quant->quant( tu, compID, pSrc, uiAbsSum, cQP, ctx );
