00903 
00904 void TrQuant::transformNxN( TransformUnit& tu, const ComponentID& compID, const QpParam& cQP, std::vector<TrMode>* trModes, const int maxCand )
00905 {
00906         CodingStructure &cs = *tu.cs;
00907   const CompArea &rect      = tu.blocks[compID];
00908   const uint32_t width      = rect.width;
00909   const uint32_t height     = rect.height;
00910 
00911   const CPelBuf  resiBuf    = cs.getResiBuf(rect);
00912 
00913   CHECK( cs.sps->getMaxTbSize() < width, "Unsupported transformation size" );
00914 
00915   int pos = 0;
00916   std::vector<TrCost> trCosts;
00917   std::vector<TrMode>::iterator it = trModes->begin();
00918   const double facBB[] = { 1.2, 1.3, 1.3, 1.4, 1.5 };
00919   while( it != trModes->end() )
00920   {
00921     tu.mtsIdx[compID] = it->first;
00922     CoeffBuf tempCoeff( m_mtsCoeffs[tu.mtsIdx[compID]], rect);
00923     if( tu.noResidual )
00924     {
00925       int sumAbs = 0;
00926       trCosts.push_back( TrCost( sumAbs, pos++ ) );
00927       it++;
00928       continue;
00929     }
00930 
00931     if ( tu.mtsIdx[compID] == MTS_SKIP )
00932     {
00933       xTransformSkip( tu, compID, resiBuf, tempCoeff.buf );
00934     }
00935     else
00936     {
00937       xT( tu, compID, resiBuf, tempCoeff, width, height );
00938     }
00939 
00940     TCoeff sumAbs = 0;
00941     for( int pos = 0; pos < width*height; pos++ )
00942     {
00943       sumAbs += abs( tempCoeff.buf[pos] );
00944     }
00945 
00946     double scaleSAD=1.0;
00947     if ( tu.mtsIdx[compID] == MTS_SKIP && ((floorLog2(width) + floorLog2(height)) & 1) == 1)
00948     {
00949       scaleSAD=1.0/1.414213562; // compensate for not scaling transform skip coefficients by 1/sqrt(2)
00950     }
00951     if (tu.mtsIdx[compID] == MTS_SKIP)
00952     {
00953       int trShift = getTransformShift(tu.cu->slice->getSPS()->getBitDepth(toChannelType(compID)), rect.size(),
00954                                       tu.cu->slice->getSPS()->getMaxLog2TrDynamicRange(toChannelType(compID)));
00955       scaleSAD *= pow(2, trShift);
00956     }
00957 
00958     trCosts.push_back( TrCost( int(std::min<double>(sumAbs*scaleSAD, std::numeric_limits<int>::max())), pos++ ) );
00959     it++;
00960   }
00961 
00962   int numTests = 0;
00963   std::vector<TrCost>::iterator itC = trCosts.begin();
00964   const double fac   = facBB[std::max(0, floorLog2(std::max(width, height)) - 2)];
00965   const double thr   = fac * trCosts.begin()->first;
00966   const double thrTS = trCosts.begin()->first;
00967   while( itC != trCosts.end() )
00968   {
00969     const bool testTr = itC->first <= ( itC->second == 1 ? thrTS : thr ) && numTests <= maxCand;
00970     trModes->at( itC->second ).second = testTr;
00971     numTests += testTr;
00972     itC++;
00973   }
00974 }
00975 
00976 void TrQuant::transformNxN( TransformUnit& tu, const ComponentID& compID, const QpParam& cQP, TCoeff& uiAbsSum, const Ctx& ctx, const bool loadTr )
00977 {
00978         CodingStructure &cs = *tu.cs;
00979   const SPS &sps            = *cs.sps;
00980   const CompArea &rect      = tu.blocks[compID];
00981   const uint32_t uiWidth        = rect.width;
00982   const uint32_t uiHeight       = rect.height;
00983 
00984   const CPelBuf resiBuf     = cs.getResiBuf(rect);
00985 
00986   if( tu.noResidual )
00987   {
00988     uiAbsSum = 0;
00989     TU::setCbfAtDepth( tu, compID, tu.depth, uiAbsSum > 0 );
00990     return;
00991   }
00992 
00993   if ((tu.cu->bdpcmMode && isLuma(compID)) || (!isLuma(compID) && tu.cu->bdpcmModeChroma))
00994   {
00995     tu.mtsIdx[compID] = MTS_SKIP;
00996   }
00997 
00998   uiAbsSum = 0;
00999 
01000   // transform and quantize
01001   CHECK(cs.sps->getMaxTbSize() < uiWidth, "Unsupported transformation size");
01002 
01003   CoeffBuf tempCoeff(loadTr ? m_mtsCoeffs[tu.mtsIdx[compID]] : m_tempCoeff, rect);
01004 
01005   DTRACE_PEL_BUF(D_RESIDUALS, resiBuf, tu, tu.cu->predMode, compID);
01006 
01007   if (!loadTr)
01008   {
01009     if (tu.mtsIdx[compID] == MTS_SKIP)
01010     {
01011       xTransformSkip(tu, compID, resiBuf, tempCoeff.buf);
01012     }
01013     else
01014     {
01015       xT(tu, compID, resiBuf, tempCoeff, uiWidth, uiHeight);
01016     }
01017   }
01018 
01019   if (sps.getUseLFNST())
01020   {
01021     xFwdLfnst(tu, compID, loadTr);
01022   }
01023 
01024   DTRACE_COEFF_BUF(D_TCOEFF, tempCoeff, tu, tu.cu->predMode, compID);
01025 
01026   xQuant(tu, compID, tempCoeff, uiAbsSum, cQP, ctx);
01027 
01028   DTRACE_COEFF_BUF(D_TCOEFF, tu.getCoeffs(compID), tu, tu.cu->predMode, compID);
01029 
01030   // set coded block flag (CBF)
01031   TU::setCbfAtDepth (tu, compID, tu.depth, uiAbsSum > 0);
01032 }
