01035 void TrQuant::xTransformSkip(const TransformUnit &tu, const ComponentID &compID, const CPelBuf &resi, TCoeff* psCoeff)
01036 {
01037   const CompArea &rect = tu.blocks[compID];
01038   const uint32_t width = rect.width;
01039   const uint32_t height = rect.height;
01040 
01041   for (uint32_t y = 0, coefficientIndex = 0; y < height; y++)
01042   {
01043     for (uint32_t x = 0; x < width; x++, coefficientIndex++)
01044     {
01045       psCoeff[coefficientIndex] = TCoeff(resi.at(x, y));
01046     }
01047   }
01048 }
